function validate(input) {
  const [{ LogInfo = [] }] = input;
  const stamp = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  for (const [account, ip, login, logout] of LogInfo) {
    if (account === null || ip === null) return 'Every session needs an account_id and an ip_address.';
    if (!stamp.test(String(login)) || !stamp.test(String(logout))) return `Account ${account} has a malformed login or logout.`;
    if (!(login < logout)) return `Account ${account} logs out at or before logging in.`;
  }
  return null;
}

