function generate(rand, size) {
  const pad = n => String(n).padStart(2, '0');
  // Times are minutes since 2021-02-01 00:00; most fall on a 30-minute grid so endpoints touch often.
  const stamp = (minutes, seconds = 0) => {
    const day = 1 + Math.floor(minutes / 1440), rest = minutes % 1440;
    return `2021-02-${pad(day)} ${pad(Math.floor(rest / 60))}:${pad(rest % 60)}:${pad(seconds)}`;
  };
  const small = size === 'small';
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const accounts = small ? 4 : 400, ips = small ? 3 : 40, days = small ? 2 : 27;
  const LogInfo = [];
  for (let i = 0; i < rows; i++) {
    if (LogInfo.length && rand() < 0.08) { LogInfo.push([...LogInfo[Math.floor(rand() * LogInfo.length)]]); continue; }
    const start = Math.floor(rand() * days) * 1440 + (small ? 16 * 60 : 0) + Math.floor(rand() * (small ? 8 : 48)) * 30;
    const end = start + (1 + Math.floor(rand() * 4)) * 30;
    // Ending one second early turns a touching pair into a near miss.
    const logout = rand() < 0.3 ? stamp(end - 1, 59) : stamp(end);
    LogInfo.push([1 + Math.floor(rand() * accounts), 1 + Math.floor(rand() * ips), stamp(start), logout]);
  }
  return [{ LogInfo }];
}
